const description = trigger.item.description ?? '';
// Match a Linear issue identifier like LIN-123 or a linear.app issue URL.
const urlMatch = description.match(/linear\.app\/[^/\s]+\/([A-Z]{2,5}-\d+)/i);
const idMatch = description.match(/\b([A-Z]{2,5}-\d{1,6})\b/);
const linearRef = urlMatch?.[1] ?? idMatch?.[1] ?? '';
return {
  linearRef,
  matchCount: linearRef ? 1 : 0
};

const ref = steps.completeLinearIssue.issueIdentifier;
const matched = steps.completeLinearIssue.matched;
return {
  text: matched
    ? `Marked Linear ${ref} as done in Linear.`
    : `Could not find a matching Linear issue for "${ref}".`
};
